import React, { useState } from 'react';
import { 
  Lock, Eye, EyeOff, Download, Trash2, 
  Database, Globe, Shield, History, Users
} from 'lucide-react';

const PrivacySettings = () => {
  const [privacySettings, setPrivacySettings] = useState({
    profileVisibility: 'private',
    dataSharing: false,
    analytics: true,
    personalizedAds: false,
    searchVisibility: true
  });

  const toggleSetting = (key) => {
    setPrivacySettings(prev => ({
      ...prev,
      [key]: !prev[key]
    }));
  };

  return (
    <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
      {/* Header */}
      <div className="flex items-center space-x-3 mb-6">
        <div className="h-12 w-12 rounded-2xl bg-gradient-to-r from-emerald-500 to-teal-400 flex items-center justify-center">
          <Lock className="h-6 w-6 text-white" />
        </div>
        <div>
          <h3 className="text-lg font-bold text-neutral-900 dark:text-white">Confidentialité et données</h3>
          <p className="text-sm text-neutral-600 dark:text-neutral-400">Contrôlez votre vie privée</p>
        </div>
      </div>

      {/* Privacy Settings */}
      <div className="space-y-6">
        {/* Profile Visibility */}
        <div className="mb-6">
          <h4 className="font-semibold text-neutral-900 dark:text-white mb-4 flex items-center">
            <Globe className="h-5 w-5 mr-2 text-blue-500" />
            Visibilité du profil
          </h4>
          <div className="grid grid-cols-3 gap-3">
            {[
              { id: 'public', label: 'Public', icon: <Globe className="h-5 w-5" /> },
              { id: 'private', label: 'Privé', icon: <Lock className="h-5 w-5" /> },
              { id: 'friends', label: 'Amis uniquement', icon: <Users className="h-5 w-5" /> }
            ].map((option) => (
              <button
                key={option.id}
                onClick={() => setPrivacySettings({...privacySettings, profileVisibility: option.id})}
                className={`p-4 rounded-2xl border-2 transition-all duration-300 ${
                  privacySettings.profileVisibility === option.id
                    ? 'border-primary-500 bg-gradient-to-r from-primary-50 to-primary-100/50 dark:from-primary-900/30 dark:to-primary-800/20'
                    : 'border-transparent hover:border-neutral-300 dark:hover:border-neutral-700'
                }`}
              >
                <div className="h-10 w-10 rounded-xl bg-primary-500/10 flex items-center justify-center mb-3 mx-auto">
                  {option.icon}
                </div>
                <p className="font-medium text-neutral-900 dark:text-white text-center">{option.label}</p>
              </button>
            ))}
          </div>
        </div>

        {/* Data Settings */}
        <div className="space-y-4">
          <h4 className="font-semibold text-neutral-900 dark:text-white mb-4 flex items-center">
            <Database className="h-5 w-5 mr-2 text-purple-500" />
            Paramètres des données
          </h4>

          {[
            {
              key: 'dataSharing',
              label: 'Partage de données',
              description: 'Partager des données anonymes pour améliorer le service',
              icon: <Database className="h-5 w-5" />
            },
            {
              key: 'analytics',
              label: 'Analytics',
              description: 'Collecter des données d\'utilisation pour l\'analyse',
              icon: <History className="h-5 w-5" />
            },
            {
              key: 'personalizedAds',
              label: 'Publicités personnalisées',
              description: 'Afficher des publicités basées sur vos intérêts',
              icon: <Eye className="h-5 w-5" />
            },
            {
              key: 'searchVisibility',
              label: 'Visibilité dans la recherche',
              description: 'Apparaître dans les résultats de recherche',
              icon: <Globe className="h-5 w-5" />
            }
          ].map((setting) => (
            <div 
              key={setting.key}
              className="flex items-center justify-between p-4 rounded-2xl bg-neutral-50 dark:bg-neutral-800/30 hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors"
            >
              <div className="flex items-center space-x-3">
                <div className="h-10 w-10 rounded-xl bg-primary-500/10 flex items-center justify-center">
                  {setting.icon}
                </div>
                <div>
                  <p className="font-medium text-neutral-900 dark:text-white">{setting.label}</p>
                  <p className="text-sm text-neutral-600 dark:text-neutral-400">{setting.description}</p>
                </div>
              </div>
              <button
                onClick={() => toggleSetting(setting.key)}
                className={`relative inline-flex h-6 w-11 items-center rounded-full transition-all duration-300 ${
                  privacySettings[setting.key]
                    ? 'bg-primary-500 hover:bg-primary-600'
                    : 'bg-neutral-300 dark:bg-neutral-700 hover:bg-neutral-400 dark:hover:bg-neutral-600'
                }`}
              >
                <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition ${
                  privacySettings[setting.key] ? 'translate-x-6' : 'translate-x-1'
                }`} />
              </button>
            </div>
          ))}
        </div>

        {/* Data Management */}
        <div className="pt-6 border-t border-neutral-200 dark:border-neutral-800">
          <h4 className="font-semibold text-neutral-900 dark:text-white mb-4 flex items-center">
            <Shield className="h-5 w-5 mr-2 text-emerald-500" />
            Gestion des données
          </h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <button className="p-4 rounded-2xl bg-gradient-to-br from-blue-50 to-blue-100/30 dark:from-blue-900/10 dark:to-blue-800/5 hover:from-blue-100 dark:hover:from-blue-900/20 transition-all duration-300 group">
              <div className="flex items-center space-x-3">
                <div className="h-10 w-10 rounded-xl bg-blue-500/10 flex items-center justify-center">
                  <Download className="h-5 w-5 text-blue-500" />
                </div>
                <div>
                  <p className="font-medium text-neutral-900 dark:text-white">Exporter mes données</p>
                  <p className="text-sm text-neutral-600 dark:text-neutral-400">Télécharger toutes vos données</p>
                </div>
              </div>
            </button>

